    public EmergencyActivationResponse confirmActivation(String commandKey, String requestId, String eventKey,
                                                         Long windowId, String amount, String role, String actor) {
        throw new UnsupportedOperationException();
    }

    /** 核销：标记已耗用数量，不回补储备，不得超过未结清量。 */
    public EmergencyActivationResponse writeOff(String commandKey, String requestId, String amount, String actor) {
        throw new UnsupportedOperationException();
    }

    /** 归还：未耗用数量回补储备，不得超过未结清量。 */
    public EmergencyActivationResponse returnWater(String commandKey, String requestId, String amount,
                                                   String actor) {
        throw new UnsupportedOperationException();
    }

    /** 查询启用请求当前状态（含两位确认人与储备剩余快照）。 */
    public EmergencyActivationResponse getRequest(String requestId) {
        throw new UnsupportedOperationException();
    }

    /** 查询储备账本。 */
    public ReserveResponse getReserve() {
        throw new UnsupportedOperationException();
    }

    /** 查询目标窗口的紧急水预占（普通排班容量不读取此数据）。 */
    public WindowEmergencyResponse getWindowEmergency(long windowId) {
        throw new UnsupportedOperationException();
    }

    /** 查询某启用单的启用/核销/归还流水。 */
    public EmergencyFlowListResponse listRequestFlows(String requestId) {
        throw new UnsupportedOperationException();
    }

    /** 查询某目标窗口的紧急流水。 */
    public EmergencyFlowListResponse listWindowFlows(long windowId) {
        throw new UnsupportedOperationException();
    }

    // ------------------------------------------------------------------
    // 内部工具（实现阶段补齐）
    // ------------------------------------------------------------------

    private <T> T runCommand(String operation, String commandKey, String params, Class<T> type,
                             Supplier<T> business) {
        throw new UnsupportedOperationException();
    }

    EmergencyEventResponse toEventResponse(EmergencyRepository.EventRow row) {
        throw new UnsupportedOperationException();
    }

    EmergencyActivationResponse toActivationResponse(EmergencyRepository.RequestRow row) {
        throw new UnsupportedOperationException();
    }

    EmergencyConfirmationView toConfirmationView(EmergencyRepository.ConfirmationRow row) {
        throw new UnsupportedOperationException();
    }

    EmergencyFlowResponse toFlowResponse(EmergencyRepository.FlowRow row) {
        throw new UnsupportedOperationException();
    }

    WindowRow requireWindow(long windowId) {
        throw new UnsupportedOperationException();
    }

    CommandRow replay(CommandRow existing, String operation, String params,
                      Class<?> type) {
        throw new UnsupportedOperationException();
    }
}

