    /** 查询启用单全部流水（启用、核销、归还）。 */
    @GetMapping("/activations/{requestId}/flows")
    public EmergencyFlowListResponse listRequestFlows(@PathVariable String requestId) {
        return service.listRequestFlows(requestId);
