    }

    /** 目标窗口的紧急水预占视图：未结清量与逐笔启用单。 */
    public record WindowEmergencyResponse(long windowId, String outstandingVolume,
                                          List<EmergencyActivationResponse> requests) {
    }

    /** 统一错误响应体。 */
    public record ErrorResponse(String code, String message) {
    }
}

